import pytest
from src.nhm import Nhm
from src.label_identification import LabelIdentification


@pytest.fixture
def nhm_ins():
    label_identification = LabelIdentification(
        ['mukesaki_kbn', 'nonyusaki_kbn', 'nonyuAlphabet', 
         'nonyuNoMin', 'nonyuNoMax'],
        ['04', '09', 'TTT', '1', '3'],
        'T1210', 'スレー'
    )
    nhm = Nhm(label_identification, 'S6-SV3400A-U-R-EX', 
              'ＳＶ－３４００ Ａ液 (UN/15KG)')

    return nhm


def test_create_nonexistent_data(nhm_ins):

    result = nhm_ins._create_nonexistent_data()
    assert result == [
                ['T1210', 'TTT01', 'S6-SV3400A-U-R-EX'],
                ['T1210', 'TTT02', 'S6-SV3400A-U-R-EX'],
                ['T1210', 'TTT03', 'S6-SV3400A-U-R-EX'],
            ]


def test_get_nhm_mukesaki(nhm_ins):
    result = nhm_ins._get_nhm_mukesaki()
    assert result == 'TTT_スレー'

